import { useEffect, useRef, useState } from "react";
import { lerp, clamp, ease } from "./helpers";

export default function MergedFraudQuestion() {
  const [progress, setProgress] = useState(0);
  const [isMobile, setIsMobile] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    check();
    window.addEventListener("resize", check, { passive: true });
    return () => window.removeEventListener("resize", check);
  }, []);

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current; if (!el) return;
      const rect = el.getBoundingClientRect();
      const p = clamp(-rect.top / (el.offsetHeight - window.innerHeight), 0, 1);
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  // ── Fraud section animations (0 → 0.35 of total scroll) ──────────
  const fraudEnd   = 0.38;
  const fp         = (s, e) => ease(clamp((progress - s) / (e - s), 0, 1));
  const titleP     = fp(0,    0.09);
  const chartP     = fp(0.05, 0.18);
  const footerP    = fp(0.22, 0.30);

  // ── Question section animations (0.35 → 1.0) ────────────────────
  const qStart     = fraudEnd;
  const title1P    = fp(qStart,        qStart + 0.08);
  const cards1P    = fp(qStart + 0.04, qStart + 0.16);
  const title2P    = fp(qStart + 0.20, qStart + 0.28);
  const cards2P    = fp(qStart + 0.26, qStart + 0.36);

  const questions = [
    { img: "/assets/question1.png", text: "Which segments are the most risk-prone?" },
    { img: "/assets/question2.png", text: "Where are the risk hotspots across the country?" },
    { img: "/assets/question3.png", text: "What correlations exist between risk rates and other factors?" },
  ];

  const people = [
    { label: "Truck drivers",     riskRate: "4.75%", meanAge: "30.90", img: "/assets/truck-driver.png" },
    { label: "Dark Store Workers", riskRate: "2.36%", meanAge: "24.34", img: "/assets/store.png" },
    { label: "Delivery Partners",  riskRate: "3.04%", meanAge: "27.94", img: "/assets/delivery.png" },
  ];

  const font = "'Inter','Helvetica Neue',sans-serif";

  return (
    // Total scroll height: 200vh (fraud) + 400vh (question) = 600vh, but merged tighter → 500vh
    <div ref={sectionRef} style={{ height: "500vh", position: "relative" }}>
      <div style={{
        position: "sticky", top: 0, height: "100vh",
        overflow: "hidden",
        background: "black",
        display: "flex", flexDirection: "column",
        alignItems: "center", justifyContent: "center",
        padding: isMobile ? "32px 20px 24px" : "40px 64px 28px",
        gap: isMobile ? 16 : 20,
      }}>

        {/* Ellipse decoration */}
        <div style={{ position: "absolute", top: 0, right: isMobile ? -200 : -430, zIndex: 0, pointerEvents: "none" }}>
          <img
            src="/assets/Ellipse.png"
            alt=""
            style={{ width: isMobile ? 500 : 900, height: isMobile ? 500 : 900, opacity: 1 }}
          />
        </div>

        {/* ══════════════════ FRAUD SECTION ══════════════════ */}

        {/* Title */}
        <div style={{
          textAlign: "center",
          opacity: titleP,
          transform: `translateY(${lerp(30, 0, titleP)}px)`,
          position: "relative", zIndex: 1,
        }}>
          <h2
            className="sm:text-[105px] text-[42px]"
            style={{ fontFamily: font, fontWeight: 700, color: "white", margin: 0, lineHeight: 1.05 }}
          >
            The Fraud Behind{" "}
            <br className="sm:flex hidden" />
            the Workforce
          </h2>
        </div>

        {/* Subtitle */}
        <p style={{
          color: "white",
          fontSize: isMobile ? "13px" : "clamp(14px,1.1vw,19px)",
          fontWeight: 600, margin: 0, textAlign: "center",
          fontFamily: font,
          opacity: titleP, transform: `translateY(${lerp(20, 0, titleP)}px)`,
          position: "relative", zIndex: 1,
        }}>
          India's gig workforce has grown from
        </p>

        {/* GIF chart */}
        <div style={{
          width: "100%", maxWidth: isMobile ? "100%" : 900,
          opacity: chartP, transform: `translateY(${lerp(20, 0, chartP)}px)`,
          position: "relative", zIndex: 1,
        }}>
          <img
            src="/assets/graph.gif"
            alt="Gig workforce growth chart"
            style={{ width: "100%", display: "block", borderRadius: 4 }}
          />

          {/* Source */}
          <div style={{ textAlign: "center", marginTop: 6, opacity: footerP }}>
            <span style={{ color: "rgba(255,255,255,0.38)", fontSize: isMobile ? 11 : 13, fontFamily: font }}>
              Source:{" "}
              <a
                href="https://www.niti.gov.in/sites/default/files/2023-06/Policy_Brief_India%27s_Booming_Gig_and_Platform_Economy_27062022.pdf"
                target="_blank" rel="noreferrer"
                style={{ color: "rgba(255,255,255,0.58)", textDecoration: "underline" }}
              >Niti Ayog</a>
              {" "}and{" "}
              <a
                href="https://www.livemint.com/money/personal-finance/indias-gig-economy-in-2025-growth-formalisation-and-financial-inclusion-explained-11753438649777.html"
                target="_blank" rel="noreferrer"
                style={{ color: "rgba(255,255,255,0.58)", textDecoration: "underline" }}
              >Mint</a>
            </span>
          </div>
        </div>

        {/* Bridge line */}
        <p style={{
          color: "white",
          fontSize: isMobile ? "14px" : "clamp(15px,1.3vw,21px)",
          fontFamily: font,
          textAlign: "center", margin: 0, maxWidth: 700,
          opacity: footerP, transform: `translateY(${lerp(16, 0, footerP)}px)`,
          position: "relative", zIndex: 1,
        }}>
          But as the workforce expands, fraud scales alongside it.
        </p>

        {/* ══════════════════ DIVIDER ══════════════════ */}
        <div style={{
          width: "100%", maxWidth: 1300,
          height: 1, background: "rgba(255,255,255,0.10)",
          opacity: title1P,
          position: "relative", zIndex: 1,
        }} />

        {/* ══════════════════ QUESTION SECTION ══════════════════ */}

        {/* Section 1: Questions */}
        <div style={{ width: "100%", maxWidth: 1300, position: "relative", zIndex: 1 }}>
          <h2
            className="sm:text-[80px] text-[36px]"
            style={{
              fontFamily: font, fontWeight: 700, color: "white",
              margin: isMobile ? "0 0 16px" : "0 0 24px",
              textAlign: "center", lineHeight: 1.08,
              opacity: title1P, transform: `translateY(${lerp(200, 0, title1P)}px)`,
            }}
          >
            This section answers questions like
          </h2>

          <div style={{
            display: "grid",
            gridTemplateColumns: isMobile ? "1fr" : "repeat(3, 1fr)",
            gap: isMobile ? 12 : 16,
            width: "100%",
          }}>
            {questions.map((q, i) => {
              const cp = ease(clamp((cards1P * 1 - i * 0.15), 0, 1));
              return (
                <div key={i} style={{
                  backgroundImage: "linear-gradient(#1d1d1d,#212121)",
                  border: "1px solid white",
                  borderRadius: 14, padding: isMobile ? "14px 16px" : "16px 18px",
                  display: "flex", alignItems: "center", gap: 16,
                  minHeight: isMobile ? 80 : 100,
                  opacity: cp,
                  transform: `translateY(${lerp(30, 0, cp)}px) scale(${lerp(0.96, 1, cp)})`,
                }}>
                  <div style={{
                    width: 64, height: 64, flexShrink: 0,
                    borderRadius: 12,
                    display: "flex", alignItems: "center", justifyContent: "center",
                  }}>
                    <img src={q.img} alt="" style={{ width: 120, height: 80, objectFit: "contain" }} />
                  </div>
                  <p style={{
                    color: "white", fontSize: isMobile ? "13px" : "clamp(13px,1.05vw,17px)",
                    fontWeight: 500, margin: 0, lineHeight: 1.5, fontFamily: font,
                  }}>{q.text}</p>
                </div>
              );
            })}
          </div>
        </div>

        {/* Divider 2 */}
        <div style={{
          width: "100%", maxWidth: 1300,
          height: 1, background: "rgba(255,255,255,0.08)",
          opacity: title2P,
          position: "relative", zIndex: 1,
        }} />

        {/* Section 2: People in focus */}
        <div style={{ width: "100%", maxWidth: 1100, position: "relative", zIndex: 1 }}>
          <h2
            className="bg-gradient-to-r from-[#cdcdcd] to-white bg-clip-text text-transparent sm:text-[80px] text-[36px]"
            style={{
              fontFamily: font, fontWeight: 700,
              margin: isMobile ? "0 0 16px" : "0 0 24px",
              textAlign: "center", lineHeight: 1.05,
              opacity: title2P, transform: `translateY(${lerp(24, 0, title2P)}px)`,
            }}
          >
            People in focus
          </h2>

          <div style={{
            display: "grid",
            gridTemplateColumns: isMobile ? "1fr" : "repeat(3, 1fr)",
            gap: isMobile ? 12 : 16,
            width: "100%",
          }}>
            {people.map((p, i) => {
              const cp = ease(clamp((cards2P * 1 - i * 0.15), 0, 1));
              return (
                <div key={i} style={{
                  background: "rgba(255,255,255,0.06)",
                  border: "1px solid rgba(255,255,255,0.1)",
                  borderRadius: 14,
                  padding: isMobile ? "18px 18px 0" : "24px 24px 0",
                  display: "flex", flexDirection: "column",
                  position: "relative", overflow: "hidden",
                  minHeight: isMobile ? 200 : 260,
                  opacity: cp, transform: `translateY(${lerp(30, 0, cp)}px)`,
                }}>
                  <div style={{ color: "#CE1010", fontSize: "16px", fontWeight: 600, marginBottom: 10, fontFamily: font }}>
                    {p.label}
                  </div>
                  <div style={{ color: "white", fontSize: "clamp(22px,2.4vw,38px)", fontWeight: 700, lineHeight: 1, fontFamily: font }}>
                    {p.riskRate}
                  </div>
                  <div style={{ color: "white", fontSize: isMobile ? 14 : 16, marginTop: 4, marginBottom: 12, fontFamily: font }}>
                    Risk Rate
                  </div>
                  <div style={{ color: "white", fontSize: isMobile ? 14 : 16, marginBottom: 6, fontFamily: font }}>
                    Mean Age
                  </div>
                  <div style={{ color: "white", fontSize: "clamp(22px,2.4vw,38px)", fontWeight: 700, lineHeight: 1, fontFamily: font }}>
                    {p.meanAge}
                  </div>
                  <div style={{ color: "white", fontSize: isMobile ? 14 : 16, marginTop: 6, marginBottom: 16, fontFamily: font }}>
                    years
                  </div>

                  <img
                    src={p.img}
                    alt={p.label}
                    style={{
                      position: "absolute", bottom: -10, right: -10,
                      width: "34%", maxWidth: 120,
                      objectFit: "contain", objectPosition: "bottom right",
                      transform: "rotate(10deg)", transformOrigin: "bottom right",
                      opacity: 0.88,
                    }}
                  />
                </div>
              );
            })}
          </div>
        </div>

      </div>
    </div>
  );
}
